CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,email text UNIQUE NOT NULL,password text NOT NULL,role text NOT NULL CHECK(role IN ('customer','staff','manager','admin')),name text NOT NULL,preferences jsonb NOT NULL DEFAULT '{"personalisation":false,"email":false,"push":false,"location":false,"interests":[]}',deleted boolean DEFAULT false);
CREATE TABLE IF NOT EXISTS sessions(token text PRIMARY KEY,user_id text REFERENCES users(id),expires_at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS consents(id text PRIMARY KEY,user_id text REFERENCES users(id),version text NOT NULL,preferences jsonb NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS menu(id text PRIMARY KEY,data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id text PRIMARY KEY,data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS tables(id text PRIMARY KEY,label text NOT NULL,enabled boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders(id text PRIMARY KEY,user_id text REFERENCES users(id),guest_hash text,request_key text UNIQUE NOT NULL,table_id text REFERENCES tables(id),collection boolean DEFAULT false,total integer NOT NULL CHECK(total>=0),discount integer NOT NULL DEFAULT 0,payment text NOT NULL CHECK(payment IN ('unpaid','paid','refunded')),status text NOT NULL,notes text NOT NULL DEFAULT '',alcohol boolean NOT NULL DEFAULT false,age_checked boolean DEFAULT false,pos_ref text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items(id text PRIMARY KEY,order_id text REFERENCES orders(id),item_id text,name text,quantity integer CHECK(quantity>0),unit_price integer NOT NULL CHECK(unit_price>=0),modifiers jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id text PRIMARY KEY,order_id text UNIQUE REFERENCES orders(id),provider text NOT NULL,amount integer NOT NULL,status text NOT NULL);
CREATE TABLE IF NOT EXISTS payment_events(id text PRIMARY KEY,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs(id text PRIMARY KEY,order_id text UNIQUE REFERENCES orders(id),status text NOT NULL,attempts integer DEFAULT 0,next_at bigint DEFAULT 0,last_error text);
CREATE TABLE IF NOT EXISTS pos_attempts(id text PRIMARY KEY,order_id text REFERENCES orders(id),success boolean NOT NULL,message text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS loyalty(id text PRIMARY KEY,user_id text REFERENCES users(id),order_id text REFERENCES orders(id),points integer NOT NULL,reason text NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(order_id,reason));
CREATE TABLE IF NOT EXISTS visits(id text PRIMARY KEY,user_id text REFERENCES users(id),day text NOT NULL,method text NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(user_id,day));
CREATE TABLE IF NOT EXISTS validations(id text PRIMARY KEY,user_id text REFERENCES users(id),kind text NOT NULL,reference text NOT NULL,staff_id text REFERENCES users(id),created_at timestamptz DEFAULT now(),UNIQUE(user_id,kind,reference));
CREATE TABLE IF NOT EXISTS offers(id text PRIMARY KEY,data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS redemptions(id text PRIMARY KEY,user_id text REFERENCES users(id),offer_id text REFERENCES offers(id),order_id text REFERENCES orders(id),status text NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(user_id,offer_id));
CREATE TABLE IF NOT EXISTS events(id text PRIMARY KEY,data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS favourites(user_id text REFERENCES users(id),event_id text REFERENCES events(id),reminder boolean DEFAULT false,PRIMARY KEY(user_id,event_id));
CREATE TABLE IF NOT EXISTS bookings(id text PRIMARY KEY,user_id text REFERENCES users(id),data jsonb NOT NULL,status text DEFAULT 'requested',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS tickets(id text PRIMARY KEY,user_id text REFERENCES users(id),event_id text REFERENCES events(id),used_at timestamptz,UNIQUE(user_id,event_id));
CREATE TABLE IF NOT EXISTS campaigns(id text PRIMARY KEY,data jsonb NOT NULL,status text NOT NULL DEFAULT 'draft',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS campaign_deliveries(id text PRIMARY KEY,campaign_id text REFERENCES campaigns(id),user_id text REFERENCES users(id),created_at timestamptz DEFAULT now(),UNIQUE(campaign_id,user_id));
CREATE TABLE IF NOT EXISTS content(id text PRIMARY KEY,data jsonb NOT NULL,status text NOT NULL DEFAULT 'needs_review',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id text PRIMARY KEY,actor text,action text NOT NULL,reference text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS venue_assets(id text PRIMARY KEY,source_url text NOT NULL,kind text NOT NULL,content_type text NOT NULL,bytes bytea NOT NULL,checksum text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS social_profiles(user_id text PRIMARY KEY REFERENCES users(id),display_name text NOT NULL,discoverable boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS circles(id text PRIMARY KEY,owner_id text REFERENCES users(id),title text NOT NULL,direct_key text UNIQUE,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS circle_members(circle_id text REFERENCES circles(id) ON DELETE CASCADE,user_id text REFERENCES users(id),status text NOT NULL CHECK(status IN ('invited','active','declined','left')),PRIMARY KEY(circle_id,user_id));
CREATE TABLE IF NOT EXISTS circle_messages(id text PRIMARY KEY,circle_id text REFERENCES circles(id) ON DELETE CASCADE,author_id text REFERENCES users(id),body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 2000),client_id text NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(circle_id,author_id,client_id));
CREATE TABLE IF NOT EXISTS circle_plans(id text PRIMARY KEY,circle_id text REFERENCES circles(id) ON DELETE CASCADE,creator_id text REFERENCES users(id),title text NOT NULL,starts_at timestamptz NOT NULL,notes text NOT NULL DEFAULT '',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS circle_rsvps(plan_id text REFERENCES circle_plans(id) ON DELETE CASCADE,user_id text REFERENCES users(id),response text NOT NULL CHECK(response IN ('yes','maybe','no')),PRIMARY KEY(plan_id,user_id));
